public RefreshFrequency xds()
{
    METInventSiteByLocationPolicyTmp     metInventSiteByLocationPolicyTmp;
    METUserSecurityGroupList             metUserSecurityGroupList;
    METUserSecurityWarehouseList         metUserSecurityWarehouseList;
    InventLocation                       inventLocation;

    Unchecked(Uncheck::XDS)
    {
        insert_recordset metInventSiteByLocationPolicyTmp(InventSiteId, Company)
          select crosscompany InventSiteId, DataAreaId from inventLocation
              group by InventSiteId, DataAreaId
              join metUserSecurityWarehouseList
                  where metUserSecurityWarehouseList.InventLocationId == inventLocation.InventLocationId
                      && metUserSecurityWarehouseList.Company == inventLocation.DataAreaId
              join metUserSecurityGroupList
                  where metUserSecurityGroupList.UserSecurityGroupId == metUserSecurityWarehouseList.UserSecurityGroupId
                     && metUserSecurityGroupList.UserId == curUserId();
    }

    return RefreshFrequency::PerSession;
}
